      pt: "O Lac de Remoray é um pequeno lago na zona fronteiriça com a Suíça. É classificado como reserva natural.",
      fr: "Le Lac de Remoray est un petit lac dans la zone frontalière avec la Suisse. Il est classé comme réserve naturelle.",
