      es: ["El valle de Muggio tiene 15 kilómetros de largo.", "La superficie es de unos 50 kilómetros cuadrados.", "El Monte Generoso tiene 1.701 metros de altura.", "El pueblo de Muggio tiene unos 200 habitantes.", "El valle es parte de la Reserva de la Biosfera de la UNESCO de los valles del Tesino.", "Los muros tradicionales de piedra seca se extienden por 40 kilómetros."],
      pt: ["O vale de Muggio tem 15 quilómetros de comprimento.", "A área é de cerca de 50 quilómetros quadrados.", "O Monte Generoso tem 1.701 metros de altura.", "A aldeia de Muggio tem cerca de 200 habitantes.", "O vale faz parte da Reserva da Biosfera da UNESCO dos vales do Ticino.", "Os tradicionais muros de pedra seca estendem-se por 40 quilómetros."],
      fr: ["La vallée de Muggio mesure 15 kilomètres de long.", "La superficie est d'environ 50 kilomètres carrés.", "Le Monte Generoso culmine à 1 701 mètres.", "Le village de Muggio compte environ 200 habitants.", "La vallée fait partie de la réserve de biosphère de l'UNESCO des vallées tessinoises.", "Les murs traditionnels en pierres sèches s'étendent sur 40 kilomètres."],
