    imageHint: "Val d'Illiez valley landscape",
    descriptionAdvanced: {
      de: "Das Val d'Illiez ist ein malerisches Seitental des Unterwallis, das sich von Monthey bis zu den beeindruckenden Dents du Midi erstreckt. Es ist Teil der Region Portes du Soleil, eines der weltweit größten grenzüberschreitenden Skigebiete. Das Tal wird durch den Fluss Vièze entwässert und umfasst die Gemeinden Champéry, Val-d'Illiez und Troistorrents. Historisch ist das Tal für seine Landwirtschaft und traditionelle Holzarchitektur bekannt, wobei Champéry bereits im 19. Jahrhundert zu einem Pionier des Alpintourismus wurde. Die Gipfelkette der Dents du Midi, mit dem Haute Cime als höchstem Punkt auf 3257 Metern, dominiert das gesamte Talpanorama. Neben dem Wintersport bietet das Tal berühmte Thermalquellen, die seit Jahrzehnten Besucher zur Erholung anziehen. Die lokale Kultur wird durch traditionelle Feste und die Produktion von regionalem Käse, wie dem AOC-zertifizierten Raclette, gepflegt.",
      hu: "A Val d'Illiez az Alsó-Wallis egyik festői mellékvölgye, amely Monthey-től a lenyűgöző Dents du Midi-ig húzódik. Része a Portes du Soleil régiónak, amely a világ egyik legnagyobb határokon átnyúló síterülete. A völgyet a Vièze folyó csapolja le, és Champéry, Val-d'Illiez, valamint Troistorrents községeket foglalja magában. Történelmileg a völgy mezőgazdaságáról és hagyományos faépítészetéről ismert, Champéry már a 19. században az alpesi turizmus úttörőjévé vált. A Dents du Midi csúcslánca, amelynek legmagasabb pontja a 3257 méteres Haute Cime, uralja az egész völgy panorámáját. A téli sportok mellett a völgy híres termálforrásokkal is rendelkezik, amelyek évtizedek óta vonzzák a pihenni vágyókat. A helyi kultúrát hagyományos fesztiválok és a regionális sajtok, például az AOC-minősítésű raclette készítése ápolja.",
      ro: "Val d'Illiez este o vale laterală pitorească din Valais-ul de Jos, care se întinde de la Monthey până la impresionanții Dents du Midi. Face parte din regiunea Portes du Soleil, una dintre cele mai mari zone de schi transfrontaliere din lume. Valea este drenată de râul Vièze și cuprinde comunele Champéry, Val-d'Illiez și Troistorrents. Istoric, valea este cunoscută pentru agricultura sa și arhitectura tradițională din lemn, Champéry devenind un pionier al turismului alpin încă din secolul al XIX-lea. Lanțul muntos Dents du Midi, cu Haute Cime ca punct culminant la 3257 de metri, domină întreaga panoramă a văii. Pe lângă sporturile de iarnă, valea oferă izvoare termale faimoase, care atrag vizitatori pentru relaxare de decenii. Cultura locală este menținută prin festivaluri tradiționale și producția de brânzeturi regionale, cum ar mi raclette-ul certificat AOC.",
      en: "Val d'Illiez is a scenic side valley of the Lower Valais, extending from Monthey to the impressive Dents du Midi peaks. It is part of the Portes du Soleil region, one of the world's largest international ski areas. The valley is drained by the Vièze river and includes the municipalities of Champéry, Val-d'Illiez, and Troistorrents. Historically, the valley is noted for its agriculture and traditional wooden architecture, with Champéry becoming a pioneer of alpine tourism as early as the 19th century. The Dents du Midi mountain range, with Haute Cime as its highest point at 3257 meters, dominates the entire valley skyline. In addition to winter sports, the valley boasts famous thermal springs that have attracted visitors for relaxation for decades. Local culture is preserved through traditional festivals and the production of regional cheeses, such as AOC-certified raclette.",
      es: "El Val d'Illiez es un valle en el cantón del Valais, Suiza, conocido por su naturaleza virgen y su agricultura tradicional. Se extiende a lo largo de 25 kilómetros desde Monthey hasta el Col de Cou. El valle se caracteriza por sus prados alpinos, bosques y el río Vièze. Es un destino popular para excursionistas y esquiadores, con numerosas rutas y estaciones de esquí como Champéry. La región alberga una diversa vida silvestre, incluyendo íbices y marmotas. Históricamente, el valle fue una importante ruta comercial a través de los Alpes.",
      pt: "O Val d'Illiez é um vale no cantão do Valais, Suíça, conhecido pela sua natureza intocada e agricultura tradicional. Estende-se por 25 quilómetros desde Monthey até ao Col de Cou. O vale é caracterizado por prados alpinos, florestas e o rio Vièze. É um destino popular para caminhantes e esquiadores, com inúmeras rotas e estâncias de esqui como Champéry. A região alberga uma vida selvagem diversificada, incluindo íbices e marmotas. Historicamente, o vale foi uma importante rota comercial através dos Alpes.",
      fr: "Le Val d'Illiez est une vallée dans le canton du Valais, en Suisse, connue pour sa nature préservée et son agriculture traditionnelle. Elle s'étend sur 25 kilomètres de Monthey au Col de Cou. La vallée est caractérisée par ses prairies alpines, ses forêts et la rivière Vièze. C'est une destination prisée des randonneurs et des skieurs, avec de nombreux itinéraires et stations de ski comme Champéry. La région abrite une faune diversifiée, dont des bouquetins et des marmottes. Historiquement, la vallée était une route commerciale importante à travers les Alpes.",
    },
    factsAdvanced: {
      de: ["Die Dents du Midi bestehen aus sieben markanten Kalksteingipfeln.", "Der Fluss Vièze fließt durch das gesamte Tal bis zur Rhone.", "Champéry liegt auf einer Höhe von 1055 Metern.", "Die Thermalquellen von Val-d'Illiez wurden im Jahr 1953 entdeckt.", "Das Tal ist Teil der grenzüberschreitenden Skiregion Portes du Soleil.", "Die Haute Cime ist mit 3257 Metern der höchste Punkt des Tals."],
      hu: ["A Dents du Midi hét jellegzetes mészkőcsúcsból áll.", "A Vièze folyó az egész völgyön keresztülfolyik a Rhone-ig.", "Champéry 1055 méteres magasságban fekszik.", "Val-d'Illiez termálforrásait 1953-ban fedezték fel.", "A völgy a határokon átnyúló Portes du Soleil sírégió része.", "A Haute Cime 3257 méterével a völgy legmagasabb pontja."],
      ro: ["Dents du Midi este format din șapte vârfuri proeminente de calcar.", "Râul Vièze curge prin întreaga vale până la fluviul Ron.", "Champéry este situat la o altitudine de 1055 metri.", "Izvoarele termale din Val-d'Illiez au fost descoperite în anul 1953.", "Valea face parte din regiunea de schi transfrontalieră Portes du Soleil.", "Haute Cime este cel mai înalt punct al văii, la 3257 de metri."],
      en: ["The Dents du Midi consist of seven prominent limestone peaks.", "The Vièze river flows through the entire valley into the Rhone.", "Champéry is located at an altitude of 1055 meters.", "The thermal springs of Val-d'Illiez were discovered in 1953.", "The valley is part of the cross-border Portes du Soleil ski area.", "Haute Cime is the highest point of the valley at 3257 meters."],
      es: ["Longitud: 25 km", "Punto más alto: Col de Cou (1.920 m)", "Río Vièze", "Estación de esquí Champéry", "Situado en el cantón del Valais", "Población de Champéry: aprox. 1.300"],
      pt: ["Comprimento: 25 km", "Ponto mais alto: Col de Cou (1.920 m)", "Rio Vièze", "Estância de esqui Champéry", "Situado no cantão do Valais", "População de Champéry: aprox. 1.300"],
      fr: ["Longueur : 25 km", "Point culminant : Col de Cou (1 920 m)", "Rivière Vièze", "Station de ski Champéry", "Situé dans le canton du Valais", "Population de Champéry : env. 1 300"],
    },
