      en: ["Canton Ticino", "Steep rock faces", "Stone villages", "Alpine valley"],
      es: ["Cantón del Tesino", "Paredes rocosas empinadas", "Pueblos de piedra", "Valle alpino"],
      pt: ["Cantão do Ticino", "Paredes rochosas íngremes", "Aldeias de pedra", "Vale alpino"],
      fr: ["Canton du Tessin", "Parois rocheuses abruptes", "Villages de pierre", "Vallée alpine"],
